def score(words):
    total = 0
    seen = []
    for w in words:
        w = w.strip().lower()
        if not w:
            continue
        if w in seen:
            total -= 1
            continue
        seen.append(w)
        if w.isdigit():
            total += int(w)
        elif len(w) > 3:
            total += 2
        else:
            total += 1
    if total < 0:
        total = 0
    return total

